from pathlib import Path
import urllib.request,json,hashlib,zipfile,time
R=Path(__file__).resolve().parent;D=R/'data'
urls=['https://www.kaggle.com/api/v1/datasets/download/mczielinski/bitcoin-historical-data?datasetVersionNumber=713','https://raw.githubusercontent.com/ff137/bitstamp-btcusd-minute-data/main/data/original/source-manifest.json']
for i,url in enumerate(urls):
 try:
  p=D/('kaggle_713.zip' if i==0 else 'source_manifest.json')
  with urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'Rizan-historical-research/1.0'}),timeout=45) as f,p.open('wb') as out:
   print('FETCH',i,f.status,f.headers.get('Content-Type'),f.headers.get('Content-Length'),flush=True)
   while block:=f.read(1024*1024):out.write(block)
  print('DONE',i,p.stat().st_size,hashlib.sha256(p.read_bytes()).hexdigest(),flush=True)
  if i==0:print('ZIP',zipfile.is_zipfile(p),flush=True)
 except Exception as e:print('FAILED',i,type(e).__name__,str(e)[:200],flush=True)

